arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_17fb0a8761af4e1fadddd3607d42aa43.Models
@using sv_17fb0a8761af4e1fadddd3607d42aa43.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h1 class="mb-4">Job Application</h1>

    @if (_submitted)
    {
        <div class="alert alert-success text-center py-5">
            <h2 class="mb-3">✅ Application Submitted!</h2>
            <p class="lead">Your application has been received.</p>
            <p class="fs-4">Application ID: <strong>@_applicationId</strong></p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="_currentStep"
                       CompletedSteps="_completedSteps"
                       OnStepClicked="GoToStep" />

        @if (!string.IsNullOrEmpty(_errorMessage))
        {
            <div class="alert alert-danger mt-3">@_errorMessage</div>
        }

        <div class="card mt-3">
            <div class="card-body">
                @switch (_currentStep)
                {
                    case 1:
                        <PersonalInfoStep @bind-FullName="_fullName"
                                          @bind-Email="_email"
                                          @bind-Phone="_phone"
                                          @bind-Address="_address" />
                        break;
                    case 2:
                        <WorkHistoryStep Entries="_workEntries" />
                        break;
                    case 3:
                        <ReferencesStep References="_references" />
                        break;
                    case 4:
                        <CoverLetterStep @bind-CoverLetter="_coverLetter"
                                         MaxLength="2000" />
                        break;
                    case 5:
                        <ReviewStep FullName="@_fullName"
                                    Email="@_email"
                                    Phone="@_phone"
                                    Address="@_address"
                                    WorkEntries="_workEntries"
                                    References="_references"
                                    CoverLetter="@_coverLetter"
