{"file_text": "@{
    var steps = new[] { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
}

<nav aria-label="Application steps">
    <ol class="step-indicator d-flex list-unstyled mb-0 p-0">
        @for (int i = 0; i < steps.Length; i++)
        {
            var stepNum = i + 1;
            var isCompleted = CompletedSteps.Contains(stepNum);
            var isCurrent = stepNum == CurrentStep;
            var isClickable = isCompleted && !isCurrent;

            <li class="step-item flex-fill text-center @(isCurrent ? "active" : isCompleted ? "completed" : "dimmed")"
                role="button"
                @onclick="() => { if (isClickable) OnStepClicked.InvokeAsync(stepNum); }">
                <div class="step-circle mx-auto mb-1
                    @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-light text-muted border")">
                    @if (isCompleted && !isCurrent)
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        <span>@stepNum</span>
                    }
                </div>
                <small class="@(isCurrent ? "fw-bold text-primary" : isCompleted ? "text-success" : "text-muted")">
                    @steps[i]
                </small>
            </li>
        }
    </ol>
</nav>

