@page "/apply"
@rendermode InteractiveServer
@using sv_17fb0a8761af4e1fadddd3607d42aa43.Models
@using sv_17fb0a8761af4e1fadddd3607d42aa43.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h1 class="mb-4">Job Application</h1>

    @if (_submitted)
    {
        <div class="alert alert-success text-center py-5">
            <h2 class="mb-3">✅ Application Submitted!</h2>
            <p class="lead">Your application has been received.</p>
            <p class="fs-4">Application ID: <strong>@_applicationId</strong></p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="_currentStep"
                       CompletedSteps="_completedSteps"
                       OnStepClicked="GoToStep" />

        @if (!string.IsNullOrEmpty(_errorMessage))
        {
            <div class="alert alert-danger mt-3">@_errorMessage</div>
        }

        <div class="card mt-3">
            <div class="card-body">
                @switch (_currentStep)
                {
                    case 1:
                        <PersonalInfoStep @bind-FullName="_fullName"
                                          @bind-Email="_email"
                                          @bind-Phone="_phone"
                                          @bind-Address="_address" />
                        break;
                    case 2:
                        <WorkHistoryStep Entries="_workEntries" />
                        break;
                    case 3:
                        <ReferencesStep References="_references" />
                        break;
                    case 4:
                        <CoverLetterStep @bind-CoverLetter="_coverLetter"
                                         MaxLength="2000" />
                        break;
                    case 5:
                        <ReviewStep FullName="@_fullName"
                                    Email="@_email"
                                    Phone="@_phone"
                                    Address="@_address"
                                    WorkEntries="_workEntries"
                                    References="_references"
                                    CoverLetter="@_coverLetter"
                                    OnEditSection="GoToStep" />
                        break;
                }
            </div>
        </div>

        <div class="d-flex justify-content-between mt-3">
            @if (_currentStep > 1)
            {
                <button class="btn btn-outline-secondary" @onclick="PreviousStep" disabled="@_isProcessing">
                    ← Back
                </button>
            }
            else
            {
                <span></span>
            }

            @if (_currentStep < 5)
            {
                <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">
                    @if (_isProcessing)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Next →
                </button>
            }
            else
            {
                <button class="btn btn-success" @onclick="SubmitApplication" disabled="@_isProcessing">
                    @if (_isProcessing)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Submit Application
                </button>
            }
        </div>
    }
</div>

@code {
    private int _currentStep = 1;
    private readonly HashSet<int> _completedSteps = new();
    private string? _errorMessage;
    private bool _isProcessing;
    private bool _submitted;
    private int _applicationId;

    // Step 1 — Personal Info
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 — Work History
    private readonly List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3 — References
    private readonly List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 — Cover Letter
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        if (step < _currentStep || _completedSteps.Contains(step))
        {
            _errorMessage = null;
            _currentStep = step;
        }
    }

    private void PreviousStep()
    {
        _errorMessage = null;
        _currentStep--;
    }

    private async Task NextStep()
    {
        _errorMessage = null;
        _isProcessing = true;

        try
        {
            if (!ValidateCurrentStep())
                return;

            if (_currentStep == 1)
            {
                var emailValid = await ApplicationService.ValidateEmailAsync(_email);
                if (!emailValid)
                {
                    _errorMessage = "Please enter a valid email address.";
                    return;
                }
            }

            _completedSteps.Add(_currentStep);
            _currentStep++;
        }
        finally
        {
            _isProcessing = false;
        }
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 1:
                if (string.IsNullOrWhiteSpace(_fullName))
                { _errorMessage = "Full name is required."; return false; }
                if (string.IsNullOrWhiteSpace(_email))
                { _errorMessage = "Email is required."; return false; }
                if (string.IsNullOrWhiteSpace(_phone))
                { _errorMessage = "Phone number is required."; return false; }
                if (string.IsNullOrWhiteSpace(_address))
                { _errorMessage = "Address is required."; return false; }
                return true;

            case 2:
                foreach (var entry in _workEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company))
                    { _errorMessage = "Company name is required for all work entries."; return false; }
                    if (string.IsNullOrWhiteSpace(entry.Title))
                    { _errorMessage = "Job title is required for all work entries."; return false; }
                    if (entry.StartDate == default)
                    { _errorMessage = "Start date is required for all work entries."; return false; }
                }
                return true;

            case 3:
                foreach (var r in _references)
                {
                    if (string.IsNullOrWhiteSpace(r.Name))
                    { _errorMessage = "Name is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Relationship))
                    { _errorMessage = "Relationship is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Email))
                    { _errorMessage = "Email is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Phone))
                    { _errorMessage = "Phone is required for all references."; return false; }
                }
                return true;

            case 4:
                if (string.IsNullOrWhiteSpace(_coverLetter))
                { _errorMessage = "Cover letter is required."; return false; }
                return true;

            default:
                return true;
        }
    }

    private async Task SubmitApplication()
    {
        _isProcessing = true;
        _errorMessage = null;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(_fullName, _email, _phone, _address),
                new WorkHistory(_workEntries.Select(e =>
                    new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)
                ).ToList()),
                _references.Select(r =>
                    new Reference(r.Name, r.Relationship, r.Email, r.Phone)
                ).ToList(),
                _coverLetter
            );

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch
        {
            _errorMessage = "An error occurred while submitting your application. Please try again.";
        }
        finally
        {
            _isProcessing = false;
        }
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

