+                        break;
+                    case 5:
+                        <ReviewStep FullName="@_fullName"
+                                    Email="@_email"
+                                    Phone="@_phone"
+                                    Address="@_address"
+                                    WorkEntries="_workEntries"
+                                    References="_references"
+                                    CoverLetter="@_coverLetter"
+                                    OnEditSection="GoToStep" />
+                        break;
+                }
+            </div>
+        </div>
+
+        <div class="d-flex justify-content-between mt-3">
+            @if (_currentStep > 1)
+            {
+                <button class="btn btn-outline-secondary" @onclick="PreviousStep" disabled="@_isProcessing">
+                    ← Back
+                </button>
+            }
+            else
+            {
+                <span></span>
+            }
+
+            @if (_currentStep < 5)
+            {
+                <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">
+                    @if (_isProcessing)
+                    {
+                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
+                    }
+                    Next →
+                </button>
+            }
+            else
+            {
+                <button class="btn btn-success" @onclick="SubmitApplication" disabled="@_isProcessing">
+                    @if (_isProcessing)
+                    {
+                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
+                    }
+                    Submit Application
+                </button>
+            }
+        </div>
+    }
